import { useState } from 'react'; import { useAppState } from '../../app/AppState'; import { Badge, Button, Card, CardHeader, Textarea } from '../../components/ui';
const prompt = `Create a Mode B script artifact for project VB-0024.\nReturn structured JSON only. Preserve shot IDs and include citations as notes.\nThis is a demo prompt; no reservation or backend task exists.`;
export function ExternalWorkspace() { const [tab, setTab] = useState('Script'); const [json, setJson] = useState(''); const [result, setResult] = useState<'idle'|'valid'|'invalid'>('idle'); const { showNotice } = useAppState(); const validate = () => { try { const parsed: unknown = JSON.parse(json); setResult(parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed) ? 'valid' : 'invalid'); } catch { setResult('invalid'); } }; return <div className="grid wide-left"><Card><CardHeader title="External task prompt" hint="Copy to ChatGPT manually · no embedded API" action={<Badge tone="amber">DEMO</Badge>} /><div className="tabs">{['Script','Storyboard','Captions'].map(item => <button key={item} className={tab === item ? 'active' : ''} onClick={() => setTab(item)}>{item}</button>)}</div><pre className="prompt">{prompt.replace('script', tab.toLowerCase())}</pre><div className="actions"><Button variant="primary" onClick={() => navigator.clipboard.writeText(prompt).then(() => showNotice('Demo prompt copied.')).catch(() => showNotice('Clipboard unavailable.'))}>Copy prompt</Button><Button onClick={() => showNotice('Demo export is available in the packaged desktop app.')}>Export .md</Button><Button onClick={() => window.open('https://chatgpt.com/', '_blank', 'noopener,noreferrer')}>Open ChatGPT</Button></div></Card><Card><CardHeader title="Import JSON workspace" hint="Syntax check only · not production schema validation" /><Textarea aria-label="Import JSON" value={json} onChange={e => { setJson(e.target.value); setResult('idle'); }} placeholder={'Paste the returned JSON here…'} /><div className="actions"><Button onClick={() => { setJson('{\n  "artifact_id": "demo_script_01",\n  "stage": "script"\n}'); setResult('idle'); }}>Use sample</Button><Button onClick={() => { setJson(''); setResult('idle'); }}>Clear</Button><Button variant="primary" onClick={validate}>Validate demo</Button></div>{result === 'valid' && <div className="info success">Valid JSON syntax · DEMO ONLY. No artifact was imported.</div>}{result === 'invalid' && <div className="info error" role="alert">Invalid JSON. Fix syntax before continuing.</div>}<Button disabled={result !== 'valid'}>Approve import · backend unavailable</Button></Card></div>; }
